class RestaurantOperationsView extends StackedView<RestaurantOperationsViewModel>{
 const RestaurantOperationsView({super.key,required this.permissions});final Set<String> permissions;
 @override RestaurantOperationsViewModel viewModelBuilder(BuildContext context)=>RestaurantOperationsViewModel(locator<OperationsService>(),locator<InventoryService>(),permissions)..load();
 @override Widget builder(BuildContext context,RestaurantOperationsViewModel vm,Widget? child)=>DefaultTabController(length:3,child:Scaffold(appBar:AppBar(title:const Text('Restaurant operations'),bottom:const TabBar(tabs:[Tab(text:'Orders'),Tab(text:'Kitchen'),Tab(text:'New order')])),body:vm.isBusy&&!vm.loaded?const Center(child:CircularProgressIndicator()):TabBarView(children:[_Orders(vm),_Kitchen(vm),_NewOrder(vm)])));
}
class RestaurantOperationsViewModel extends BaseViewModel{
 RestaurantOperationsViewModel(this.api,this.inventory,this.permissions);final OperationsService api;final InventoryService inventory;final Set<String> permissions;bool loaded=false;String? error;List<Map<String,dynamic>> orders=[],tickets=[],products=[];List<dynamic> branches=[];String branchId='';
 bool get canCreate=>permissions.contains('orders.create');bool get canUpdate=>permissions.contains('orders.status.update');bool get canKitchen=>permissions.contains('kitchen.orders.view');
 Future<void> load() async{setBusy(true);error=null;try{final r=await Future.wait([api.orders(),api.kitchenQueue(),api.menu(),inventory.branches()]);orders=List<Map<String,dynamic>>.from(r[0] as List);tickets=List<Map<String,dynamic>>.from(r[1] as List);products=List<Map<String,dynamic>>.from(r[2] as List);branches=r[3] as List;if(branches.isNotEmpty&&!branches.any((b)=>'${b.id}'==branchId))branchId='${branches.first.id}';loaded=true;}catch(e){error=e.toString();}finally{setBusy(false);notifyListeners();}}
 Future<void> changeStatus(String id,String status) async{await _run(()=>api.updateOrder(id,status));}
 Future<void> kitchen(String id,String action) async{await _run(()=>api.kitchenAction(id,action));}
 Future<void> create(String type,List<Map<String,dynamic>> lines,{String? table,String? name,String? phone,String? address}) async{await _run(()=>api.createOrder(branchId:branchId,orderType:type,items:lines,tableLabel:table,customerName:name,customerPhone:phone,deliveryAddress:address));}
 Future<void> _run(Future<void> Function() action) async{setBusy(true);error=null;try{await action();await load();}catch(e){error=e.toString();}finally{setBusy(false);notifyListeners();}}
}
class _Orders extends StatelessWidget{const _Orders(this.vm);final RestaurantOperationsViewModel vm;
 @override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:vm.load,child:ListView(padding:const EdgeInsets.all(12),children:[if(vm.error!=null)Text(vm.error!,style:TextStyle(color:Theme.of(context).colorScheme.error)),if(vm.orders.isEmpty)const Text('No orders found.'),...vm.orders.map((o){final id='${o['id']}';final status='${o['status']??'placed'}';final items=(o['items'] as List? ?? []);return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${o['orderNumber']??'Order #$id'}',style:Theme.of(context).textTheme.titleMedium),Text('${o['orderType']} • ${o['tableLabel']??o['customerName']??''}'),Text('Status: $status • PKR ${o['grandTotal']??''}'),Text(items.map((i)=>'${i['quantity']} × ${i['productName']}').join(', ')),if(vm.canUpdate&&status=='placed')Align(alignment:Alignment.centerRight,child:TextButton(onPressed:vm.isBusy?null:()=>vm.changeStatus(id,'confirmed'),child:const Text('Confirm order')))])));})]));
}
class _Kitchen extends StatelessWidget{const _Kitchen(this.vm);final RestaurantOperationsViewModel vm;
 @override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:vm.load,child:ListView(padding:const EdgeInsets.all(12),children:[if(vm.error!=null)Text(vm.error!),if(vm.tickets.isEmpty)const Text('Kitchen queue is empty.'),...vm.tickets.map((t){final id='${t['id']}';final status='${t['status']}';final order=t['order'] as Map? ?? const {};final items=t['items'] as List? ?? [];return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${t['ticketNumber']??'Ticket #$id'}',style:Theme.of(context).textTheme.titleMedium),Text('Order ${order['orderNumber']??''} • ${order['tableLabel']??order['orderType']??''}'),...items.map((i)=>ListTile(dense:true,title:Text('${i['quantity']} × ${i['productName']} ${i['variantName']??''}'),subtitle:Text('${i['notes']??''}'))),if(status=='pending')FilledButton(onPressed:vm.isBusy?null:()=>vm.kitchen(id,'prepare'),child:const Text('Start preparing')) else if(status=='preparing')FilledButton(onPressed:vm.isBusy?null:()=>vm.kitchen(id,'ready'),child:const Text('Mark ready'))])));})]));
}
class _NewOrder extends StatefulWidget{const _NewOrder(this.vm);final RestaurantOperationsViewModel vm;@override State<_NewOrder> createState()=>_NewOrderState();}
class _NewOrderState extends State<_NewOrder>{String type='takeaway';String? variantId;final table=TextEditingController(),name=TextEditingController(),phone=TextEditingController(),address=TextEditingController();final Map<String,int> cart={};
 @override void dispose(){table.dispose();name.dispose();phone.dispose();address.dispose();super.dispose();}
 List<Map<String,dynamic>> get variants{final out=<Map<String,dynamic>>[];for(final p in widget.vm.products){final vs=p['variants'] as List? ?? p['productVariants'] as List? ?? [];for(final v in vs){out.add({...Map<String,dynamic>.from(v as Map),'_productName':p['name']??'Product'});}}return out;}
 @override Widget build(BuildContext context){final vm=widget.vm;final available=variants;return ListView(padding:const EdgeInsets.all(16),children:[if(!vm.canCreate)const Text('Your account does not have order creation permission.') else if(vm.branches.isEmpty)const Text('No active branch is available.') else ...[DropdownButtonFormField<String>(value:vm.branchId,decoration:const InputDecoration(labelText:'Branch'),items:vm.branches.map((b)=>DropdownMenuItem(value:'${b.id}',child:Text(b.name))).toList(),onChanged:(v)=>setState(()=>vm.branchId=v??vm.branchId)),DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Order type'),items:const [DropdownMenuItem(value:'takeaway',child:Text('Takeaway')),DropdownMenuItem(value:'dine_in',child:Text('Dine in')),DropdownMenuItem(value:'delivery',child:Text('Delivery'))],onChanged:(v)=>setState(()=>type=v??'takeaway')),if(type=='dine_in')TextField(controller:table,decoration:const InputDecoration(labelText:'Table label')),if(type=='delivery')TextField(controller:address,decoration:const InputDecoration(labelText:'Delivery address')),TextField(controller:name,decoration:const InputDecoration(labelText:'Customer name (optional)')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Customer phone (optional)')),const SizedBox(height:12),Text('Menu products',style:Theme.of(context).textTheme.titleMedium),if(available.isEmpty)const Text('No active product variants returned by the menu API.'),...available.map((v){final id='${v['id']}';final count=cart[id]??0;return Card(child:ListTile(title:Text('${v['_productName']} • ${v['name']??v['variantName']??'Variant'}'),subtitle:Text('PKR ${v['basePrice']??v['salePrice']??''}'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:count==0?null:()=>setState(()=>cart[id]=count-1),icon:const Icon(Icons.remove)),Text('$count'),IconButton(onPressed:()=>setState(()=>cart[id]=count+1),icon:const Icon(Icons.add))])));}),const SizedBox(height:12),FilledButton(onPressed:vm.isBusy||cart.values.every((q)=>q==0)|| (type=='dine_in'&&table.text.trim().isEmpty)||(type=='delivery'&&address.text.trim().isEmpty)?null:()=>vm.create(type,cart.entries.where((e)=>e.value>0).map((e)=>{'variantId':int.parse(e.key),'quantity':e.value}).toList(),table:table.text.trim(),name:name.text.trim(),phone:phone.text.trim(),address:address.text.trim()),child:const Text('Place order'))],if(vm.error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(vm.error!,style:TextStyle(color:Theme.of(context).colorScheme.error))) ]);}
}